import { Worker } from 'node:worker_threads';
import type { CfMod } from '../types/CurseForge.js';

type MatchType = 'exactName' | 'exactSlug' | 'startsWith' | 'contains' | 'tokenOverlap' | 'levenshtein' | 'unknown';
export type RankedCandidate = { mod: CfMod; score: number; matchType: MatchType };

let singleton: Worker | null = null;
let pending = new Map<number, { resolve: (v: RankedCandidate[]) => void; reject: (e: any) => void; timer: NodeJS.Timeout }>();
let nextId = 1;

function ensureWorker(): Worker {
  if (singleton) return singleton;
  const devUrl = new URL('./cf-rank-worker.js', import.meta.url);
  const bundledUrl = new URL('./workers/cf-rank-worker.js', import.meta.url);
  try {
    singleton = new Worker(devUrl);
  } catch {
    singleton = new Worker(bundledUrl);
  }
  singleton.on('message', (msg: any) => {
    const id = msg?.id as number | undefined;
    if (!id) return;
    const entry = pending.get(id);
    if (!entry) return;
    clearTimeout(entry.timer);
    pending.delete(id);
    if (msg && msg.ok) entry.resolve(msg.ranked as RankedCandidate[]);
    else entry.reject(new Error(msg?.error || 'Ranking worker failed'));
  });
  singleton.on('error', (err) => {
    // fail all pending
    for (const [id, p] of pending) {
      clearTimeout(p.timer);
      p.reject(err);
      pending.delete(id);
    }
    singleton = null;
  });
  singleton.on('exit', (code) => {
    if (code !== 0) {
      for (const [id, p] of pending) {
        clearTimeout(p.timer);
        p.reject(new Error(`Ranking worker exited with code ${code}`));
        pending.delete(id);
      }
    }
    singleton = null;
  });
  return singleton;
}

export async function rankCandidatesInWorker(items: any[], query: string, opts?: { timeoutMs?: number }): Promise<RankedCandidate[]> {
  const timeoutMs = opts?.timeoutMs ?? 10_000;
  const worker = ensureWorker();
  const id = nextId++;
  return await new Promise<RankedCandidate[]>((resolve, reject) => {
    const timer = setTimeout(() => {
      pending.delete(id);
      reject(new Error('Ranking worker timed out'));
    }, timeoutMs);
    pending.set(id, { resolve, reject, timer });
    worker.postMessage({ type: 'rank', id, items, query });
  });
}
